import{_ as r,o as t,c as a,ag as o}from"./chunks/framework.D9ghT4bC.js";const s=JSON.parse('{"title":"多人游戏","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Other/Multiplayer.md","filePath":"zh/Other/Multiplayer.md"}'),l={name:"zh/Other/Multiplayer.md"};function i(c,e,d,n,h,u){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="多人游戏" tabindex="-1">多人游戏 <a class="header-anchor" href="#多人游戏" aria-label="Permalink to &quot;多人游戏&quot;">​</a></h1><p>Unciv 的多人游戏基于简单的存档文件上传/下载，因此默认基于免费 Dropbox 账户。不过，很多人都在用这个默认方案，所以能否稳定访问并不确定。要自建服务器，请看<a href="#架设多人游戏服务器">架设多人游戏服务器</a>。</p><h2 id="如何游玩" tabindex="-1">如何游玩 <a class="header-anchor" href="#如何游玩" aria-label="Permalink to &quot;如何游玩&quot;">​</a></h2><ol start="0"><li>确保所有人都使用同一个多人服务器（<code>主菜单 -&gt; 选项 -&gt; 多人游戏</code>）</li><li>让所有玩家把他们的用户 ID 发给你（<code>主菜单 -&gt; 多人游戏 -&gt; 复制用户 ID</code>）。 <ul><li>（可选）把这些用户 ID 加入你的好友列表（<code>主菜单 -&gt; 多人游戏 -&gt; 好友列表</code>）。</li></ul></li><li>在 <code>主菜单 -&gt; 开始新游戏</code> 中，勾选左侧的 <code>在线多人游戏</code>。在右侧添加更多人类玩家，输入你想一起玩的玩家的用户 ID。点击 <code>开始游戏！</code>。</li><li>游戏 ID 会自动复制到你的剪贴板。（如果弄丢了，可以从 <code>主菜单 -&gt; 多人游戏 -&gt; 复制游戏 ID</code> 重新获取。）把这个游戏 ID 发给其他玩家。</li><li>其他玩家需要进入 <code>主菜单 -&gt; 多人游戏 -&gt; 添加多人游戏</code>，输入你发给他们的游戏 ID。然后他们就可以从多人游戏界面加入游戏了。</li></ol><h2 id="架设多人游戏服务器" tabindex="-1">架设多人游戏服务器 <a class="header-anchor" href="#架设多人游戏服务器" aria-label="Permalink to &quot;架设多人游戏服务器&quot;">​</a></h2><p>由于 Dropbox API 的某些限制，加上当前玩家的涌入，我们已经多次达到 Dropbox 不可用的地步。</p><p>因此，你现在可以在任何能运行 Java 程序的电脑上架设自己的 Unciv 服务器。</p><p>本指南面向对电脑软件有中等技术水平、能够上网搜索学习未知内容的人。如果你完全是新手，不投入较多时间学习的话可能跟不上。</p><p>如果你精通服务器架设，文末还有另一份指南。</p><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><p>开始之前，你必须安装 Java JDK。还需要下载<a href="https://github.com/yairm210/Unciv/releases/latest/download/UncivServer.jar" target="_blank" rel="noreferrer">最新的 UncivServer.jar</a>。</p><p>在 <code>UncivServer.jar</code> 文件所在的目录下，创建一个名为 &quot;MultiplayerFiles&quot; 的文件夹，打开终端（Windows 中在文件夹内 Shift+右键），然后在目录中运行以下命令： <code>java -jar UncivServer.jar</code></p><p>你的服务器就启动了！</p><p>要检查是否一切正常，可以在同一台电脑上启动 Unciv，进入 &quot;选项 &gt; 多人游戏&quot;，在 &quot;服务器地址&quot; 中输入 <code>http://localhost:8080</code>，点击 &quot;检查服务器连接&quot;。你应该会看到 &quot;成功！&quot; 的结果，说明一切正常！</p><p>要连接本地网络之外的其他设备，或让服务器可以从互联网访问，你需要一个公网 IP。如果你的 ISP 已经提供了公网 IP，在路由器上转发你的服务器端口（默认 8080），你的服务器就暴露到互联网上了！这种情况下你也可以使用 <code>http://&lt;你的公网IP&gt;:&lt;你转发的端口&gt;</code>。例如，如果你有 IP <code>203.0.113.1</code> 并把服务器端口转发到 <code>1234</code>，你的服务器就可以从互联网通过 <code>http://203.0.113.1:1234</code> 访问。另外，由于 <code>HTTP</code> 协议默认端口是 <code>80</code>，如果你把服务器转发到 <code>80</code> 端口，就不需要指定端口了。例如，如果你把服务器端口转发到公网 IP 的 <code>80</code> 端口，你的服务器将暴露在 <code>http://&lt;你的公网IP&gt;</code>，即 <code>http://203.0.113.1</code>。</p><p>在另一台设备上，输入你的服务器 URL（<code>http://&lt;你的IP地址&gt;:&lt;你选择的端口&gt;</code>），在新设备上点击 &#39;检查连接&#39;，如果得到同样的 &quot;成功！&quot; 结果——恭喜，你们连接到同一个服务器了，可以开始多人游戏了！</p><p>请注意：</p><ul><li>未连接到同一服务器的设备<em>无法</em>一起参与多人游戏</li><li>在很多地方，你的外网 IP 会定期变化。如果是这样，你要么一直更新 IP，要么使用动态 DNS 之类的服务。</li><li>要从 <code>80</code> 或 <code>443</code> 之类的特殊端口启动服务器，需要管理员权限。如果要用这些端口，请以管理员身份运行 PowerShell。不过，如果你用路由器做端口转发，其实不需要这样做。你可以从 <code>8080</code> 端口启动服务器，再转发到 <code>80</code>。</li></ul><h3 id="给有架设经验的人" tabindex="-1">给有架设经验的人 <a class="header-anchor" href="#给有架设经验的人" aria-label="Permalink to &quot;给有架设经验的人&quot;">​</a></h3><ul><li>安装 Java JDK</li><li>下载<a href="https://github.com/yairm210/Unciv/releases/latest/download/UncivServer.jar" target="_blank" rel="noreferrer">最新的 UncivServer.jar</a>（也可以直接用那个链接自动更新）</li><li>用 <code>java -jar UncivServer.jar --help</code> 查看选项 <ul><li>服务器运行在指定端口（<code>-p</code>，默认 <code>8080</code>），文件写入指定文件夹（<code>-f</code>，默认 <code>./MultiplayerFiles/</code>），所以需要相应权限。</li></ul></li><li>运行它：<code>java -jar UncivServer.jar -p 8080 -f /some/folder/</code><ul><li>它基本上就是在 HTTP 上做简单的文件存储。</li><li>游戏结束或在客户端侧删除时，文件不会自动清理</li></ul></li></ul><h2 id="第三方-非官方-自建-unciv-服务器软件" tabindex="-1">第三方（非官方）自建 Unciv 服务器软件 <a class="header-anchor" href="#第三方-非官方-自建-unciv-服务器软件" aria-label="Permalink to &quot;第三方（非官方）自建 Unciv 服务器软件&quot;">​</a></h2><ul><li><a href="https://github.com/Mape6/Unciv_server" target="_blank" rel="noreferrer">https://github.com/Mape6/Unciv_server</a>（Python）</li><li><a href="https://gitlab.com/azzurite/unciv-server" target="_blank" rel="noreferrer">https://gitlab.com/azzurite/unciv-server</a>（NodeJS）</li><li><a href="https://github.com/oynqr/rust_unciv_server" target="_blank" rel="noreferrer">https://github.com/oynqr/rust_unciv_server</a>（Rust）</li><li><a href="https://github.com/touhidurrr/UncivServer.xyz" target="_blank" rel="noreferrer">https://github.com/touhidurrr/UncivServer.xyz</a>（TypeScript | Bun）</li></ul><h2 id="第三方-非官方-公共-unciv-服务器" tabindex="-1">第三方（非官方）公共 Unciv 服务器 <a class="header-anchor" href="#第三方-非官方-公共-unciv-服务器" aria-label="Permalink to &quot;第三方（非官方）公共 Unciv 服务器&quot;">​</a></h2><p>这些服务器由社区运营，<strong>不是</strong>官方服务器。这些服务器可能（暂时或永久）不可用，并丢失你的游戏存档。它们还可能收集你的 IP、游戏频率或其他数据。只有在你接受这些风险并信任服务器所有者时才使用。</p><ul><li><a href="https://uncivserver.xyz/" target="_blank" rel="noreferrer"><code>https://uncivserver.xyz/</code></a> - 由 <a href="https://github.com/touhidurrr" target="_blank" rel="noreferrer">@touhidurrr</a> 在<a href="https://discord.gg/H9em4ws8XP" target="_blank" rel="noreferrer">他们的 Discord</a> 运营（<a href="https://github.com/touhidurrr/UncivServer.xyz/" target="_blank" rel="noreferrer">源码</a>）</li></ul>',25)])])}const v=r(l,[["render",i]]);export{s as __pageData,v as default};
